end

function InvisibleSkill:RegistEvent()
    --Events.AddListener(ParkourGameUtil.Events.PlayerOnHit, Bind(self, self.OnPlayerOnHit))
end
function InvisibleSkill:CanUse()
    --printError("-CanUse- energy = " .. tostring(self.energy))
    return self.energy >= self.energyNeed
end

function InvisibleSkill:Use()
    --printError("-use-")
