    self.stateFrameCount = 0
    self.health = self.maxHp
    self.controller.transform.localPosition = Vector3(0, 0, 0)
    self.rigidBody.velocity = Vector3.zero
end




function ParkourPlayerController:Init()

    self.isOutOfRange = false -- role 是否出界
    self.debug = {}
    self.debug.tf1 = ParkourGameDebug.CreateNewPrimitive( "debug_cat_1", self.controller.gameObject.transform, Color.red )
