    ---@type UnityEngine.Rigidbody
    self.rigidBody = KTool.GetComponent(self.controller.gameObject, typeof(Rigidbody))
    self.animator = self.controller:GetComponent(typeof(Animator))

    self.palyerParamsTF = self.controller.transform.parent:Find("PlayerParams")
    assert( isNotNull(self.palyerParamsTF) )

    self:_ReadParams()

    -- 找到 头部节点:
    self.headTF = nil
    local tfComps = self.controller.transform:GetComponentsInChildren(typeof(Transform),true) -- 包含自己
    for i=0, tfComps.Length-1 do 
        local tf = tfComps[i]
        if isNotNull(tf) and string.lower(tf.name) == "head_m" then 
            self.headTF = tf
        end     
    end
    assert( isNotNull(self.headTF) )

    -- 先把这些 fx 加载好:
    self:SetRoleFX( "fx_role_death", false )
    self:SetRoleFX( "fx_role_jump2", false )
    self:SetRoleFX( "fx_role_huachan", false, false, true )
