    --- 
    self:SetRoleFX( "fx_Gain_get_green", false, false, true )
    self:SetRoleFX( "fx_Gain_get_blue", false, false, true )
    self:SetRoleFX( "fx_Gain_get_yellow", false, false, true )

    self.isInit = true
end


function ParkourPlayerController:_ReadParams()
    local luaParams = KTool.GetComponent(self.palyerParamsTF.gameObject, typeof(LuaParameters))
    self.jumpForce = LuaParametersReader.Read(luaParams, "jumpForce", LuaParametersReader.Type.Float)
    self.jumpForce2 = LuaParametersReader.Read(luaParams, "jumpForce2", LuaParametersReader.Type.Float)
    self.centerPos = LuaParametersReader.Read(luaParams, "centerPos", LuaParametersReader.Type.Float)
    self.backToCenterSpeed = LuaParametersReader.Read(luaParams, "backToCenterSpeed", LuaParametersReader.Type.Float)
    local gravity = LuaParametersReader.Read(luaParams, "gravity", LuaParametersReader.Type.Float)
    if gravity ~= checkNumber(self.gravity) then
        self.gravity = gravity
        Physics.gravity = Vector3(0, self.gravity, 0)
    end
end


