-- ParkourGameRunner 中被调用
function ParkourPlayerController:Update()
    if self.isInit ~= true then 
        return
    end 

    self.hitCD = self.hitCD - Time.deltaTime
    self.stateFrameCount = self.stateFrameCount + 1

    self:_HandleInput()

    -- Action:
    self:_HandleState()

    self._isOnGround:Sync()

    self:_TickBuff(Time.deltaTime)
    
    if Application.isEditor then
        self:_ReadParams()
    end

    self:_ResetInput()
    self:_CheckOutOfRange()

    -- 限制 猫的最大 下落速度: -- !!! 防止碰撞体过穿, 导致猫掉到地板下面去
    local maxFallSpeed = -18
    local velocity = self.rigidBody.velocity
    if velocity.y < maxFallSpeed then 
        velocity.y = maxFallSpeed
        self.rigidBody.velocity = velocity
    end 
end


-- ParkourGameRunner 中被调用
function ParkourPlayerController:FixedUpdate()
    if self.isInit ~= true then 
        return
    end 
    self:TryBackToCenter()
end


