function ParkourPlayerController:_HandleInput()
    --测试用,改成UI按钮点击
    parkourInput:TestKeyboradUpdate2()
    self.inputData.run = parkourInput.runEvent == 1 -- 这是系统控制的, 不是玩家输入的

    if self.forbidInput ~= true then
        self.inputData.jump = parkourInput.jumpEvent == 1
        self.inputData.slide = parkourInput.slideEvent == 1 or parkourInput.slideEvent == 2
