    self.inputData.jump = false
    self.inputData.slide = false
    self.inputData.skill = 0
    parkourInput:AfterLogic()    
end



-- !!! 未来写新的状态切换
function ParkourPlayerController:_HandleState()

    self:_CheckGround2()

    if self.state == PlayerState.Idle then -- =============================================
        
        if self.inputData.run == true then 
            self:ChangeState(PlayerState.Run)
        end

    elseif self.state == PlayerState.Run then -- =============================================

        if self.inputData.run == false then 
            self:ChangeState(PlayerState.Idle)
            return
        end

        -- 无敌冲刺:
        if self.conditonState.Invincible == true then 
            self:ChangeState(PlayerState.InvincibleDash)
            return
        end

    
        if self.inputData.jump and self:_IsTouchCeil( 1 )==false then
            self:ChangeState(PlayerState.Jump)
            self.jumpNum = 1
            self.rigidBody:AddForce(Vector3.up * self.jumpForce, CS.UnityEngine.ForceMode.Impulse) -- todo 别用force
            return
        end

        if self.inputData.slide then
            ParkourGameUtil.SetRoleCollider( self.controller.gameObject, ParkourGameUtil.roleSlideColliderHeight )
            self:ChangeState(PlayerState.Slide)
            return
        end

        if self.inputData.skill ~= 0 then
            --printError(" 发 -- skill = " .. tostring(self.inputData.skill))
            if self.invisibleSkill:CanUse() then
                --printError(" 发 -2-")
                self.invisibleSkill:Use()
            end
        end


    elseif self.state == PlayerState.Jump then -- =============================================
        --print("s - Jump")
        
        if self.inputData.jump and self:_IsTouchCeil( 1 )==false then
            self:ChangeState(PlayerState.Jump2)
            self.jumpNum = self.jumpNum + 1
            self.rigidBody.velocity = Vector3.zero
            self.rigidBody:AddForce(Vector3.up * self.jumpForce2, CS.UnityEngine.ForceMode.Impulse) -- todo 别用force
            return
        end


        if self:_IsTouchCeil( 0.3 ) and self.stateFrameCount > 1 then 
            print("撞到天花板了 -1-")
            self.rigidBody.velocity = Vector3.zero
            self:ChangeState(PlayerState.Falling)
            return
        end 

        if self.stateFrameCount > 2 and self.rigidBody.velocity.y < 0 then 
            self:ChangeState(PlayerState.Falling)
            return
        end 

        -- 无敌冲刺:
        if self.conditonState.Invincible == true then 
            self:ChangeState(PlayerState.InvincibleDash)
            return
        end
        

    elseif self.state == PlayerState.Jump2 then -- =============================================
        --print("s - Jump 2")

        if  self:_IsTouchCeil( 0.3 ) and self.stateFrameCount > 1 then 
            print("撞到天花板了 -2-")
            self.rigidBody.velocity = Vector3.zero
            self:ChangeState(PlayerState.Falling)
            return
        end 
        
        if self.stateFrameCount > 2 and self.rigidBody.velocity.y < 0 then 
            self:ChangeState(PlayerState.Falling)
            return
        end 

        -- 无敌冲刺:
        if self.conditonState.Invincible == true then 
            self:ChangeState(PlayerState.InvincibleDash)
            return
        end


    elseif self.state == PlayerState.Falling then -- =============================================
        --print("s - Falling")

        if self.jumpNum < 2 and self.inputData.jump and self:_IsTouchCeil( 1 )==false then
            self:ChangeState(PlayerState.Jump2)
            self.jumpNum = self.jumpNum + 1
            self.rigidBody.velocity = Vector3.zero
            --self.rigidBody.velocity = Vector3( 0, 20, 0 )
            self.rigidBody:AddForce(Vector3.up * self.jumpForce2, CS.UnityEngine.ForceMode.Impulse) -- todo 别用force
            return
        end

        if self._isOnGround.current then 
            --printError("地")
            self:ChangeState(PlayerState.Run)
            return
        end 

        -- 无敌冲刺:
        if self.conditonState.Invincible == true then 
            self:ChangeState(PlayerState.InvincibleDash)
            return
        end

    elseif self.state == PlayerState.Slide then -- =============================================
        --print("s - Slide")

        local isGetCollide = self:_CheckRoleNormalCapsuleCollider( false ) -- 防止role在夹缝里恢复, 然后被挤到地板下面去
        if not self.inputData.slide and isGetCollide ~= true then
            ParkourGameUtil.SetRoleCollider( self.controller.gameObject, ParkourGameUtil.roleNormalColliderHeight )
            self:ChangeState(PlayerState.Run)

            self:SetRoleFX( "fx_role_huachan", false, false, true )
            return
        end

    elseif self.state == PlayerState.InvincibleDash then -- =============================================
        --print("s - InvincibleDash")

        if self.conditonState.Invincible ~= true then 
            self:ChangeState(PlayerState.Run)
            return
        end

    elseif self.state == PlayerState.OnHit then -- =============================================
        --print("s - OnHit")
        
        -- 等动画播完后 自动回到 run:
        -- local animatorStateInfo = self:_GetCurrentAnimatorStateInfo()
        -- if self.stateFrameCount > 5 and string.lower(animatorStateInfo.shortNameHash) ~= "hit" then 
        --     --printError( "on hit 播放完毕: " .. tostring(animatorStateInfo.shortNameHash) )
        --     self:ChangeState(PlayerState.Run)
        -- end 

    end
end



function ParkourPlayerController:_GetCurrentAnimatorStateInfo()
    if isNull( self.animator ) then 
        printError("异常 role Animator is nil")
        return nil
    end
    return self.animator:GetCurrentAnimatorStateInfo(0)
end



