-- 在猫头后面一点位置投射个 球体, 来检测头顶上方是否有挡板
---@return boolean
function ParkourPlayerController:_IsTouchCeil( h_, isdebug_ )
    local radius = h_ * 0.5
    local midPos  = self.headTF.position + Vector3.up * radius + Vector3.left * radius * 1.5 -- 京可能后移来规避前方的碰撞体, 简陋的方法
    local numFound = Physics.OverlapSphereNonAlloc(midPos, radius, self.colliders, -1, QueryTriggerInteraction.Ignore) -- layerMask 暂时未设置
    if isdebug_ == true then
        ParkourGameDebug.DrawCubePole( self.debug.tf1, midPos - Vector3.up * radius, midPos + Vector3.up * radius, 0.1 )
    end
    ---
    for i=0, numFound-1 do 
        local collider = self.colliders[i]
        if isNotNull(collider) and collider.transform ~= self.controller.transform then
            if isdebug_ == true then
                printError( "Touch Ceil-> " .. collider.name)
            end 
            --printError("天花板")
            return true
        end
    end
    return false
end



-- 当前是否站在地面上
function ParkourPlayerController:_CheckGround2()

    -- 前后两个高度做向下检测, 任意一个命中就算成立
    local numFound1 = Physics.OverlapSphereNonAlloc(self.controller.transform.position + Vector3.right * 0.5, GrounTestDistance, self.colliders, 15, QueryTriggerInteraction.Ignore)
    local numFound2 = Physics.OverlapSphereNonAlloc(self.controller.transform.position - Vector3.right * 0.2, GrounTestDistance, self.colliders, 15, QueryTriggerInteraction.Ignore)
    if numFound1 > 0 or numFound2 > 0 then 
        self._isOnGround:SetCurrent( true )
    else 
        self._isOnGround:SetCurrent( false )
    end 
end




function ParkourPlayerController:ChangeState(state)

    if self.state ~= state then
        self.stateFrameCount = 0
        self.preState = self.state
        self.state = state
        self:_ChangeAnim()
    end
end



-- 只有当 state 发生切换时, 才调用本函数:
function ParkourPlayerController:_ChangeAnim()
    local _PlayAnim = function( id )
        self.animator:SetInteger( act_id, id )
    end

    if self.state == PlayerState.Idle then
        --print("Idle")
        _PlayAnim( 0 )

    elseif self.state == PlayerState.Run then
        --print("Run")

        _PlayAnim( 1 )
        if self.preState == PlayerState.Slide then 
            self.animator:Play( "run", -1 ) -- 动画瞬切            
        end         

    elseif self.state == PlayerState.Jump then
        --print("Jump")

        _PlayAnim( 2 )
        self.animator:Play( "jump_1", -1 ) -- 动画瞬切

        CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_jump1_12001801" )

    elseif self.state == PlayerState.Jump2 then
        --print("Jump2")

        _PlayAnim( 2 ) --若从 Falling 切入 Jump2, 此时 act 值仍保留为 22, 会导致 二段跳播放失败 (又进入 Falling 了...)
        self.animator:Play( "jump_2", -1 ) -- 动画瞬切
        self:SetRoleFX( "fx_role_jump2", true )

        CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_jump2_12001801" )

    elseif self.state == PlayerState.Falling then
        --print("Falling")

        if self.preState ~= PlayerState.Run then 
            _PlayAnim( 22 )
        end 

    elseif self.state == PlayerState.Slide then -- 滑铲
        --printError("Slide, last = " .. tostring(self.preState))
        _PlayAnim( 6 )
        self.animator:Play( "sliding", -1 ) -- 动画瞬切
        
        self:SetRoleFX( "fx_role_huachan", true, false, true ) 

        CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_sliding1_12001801" )

    elseif self.state == PlayerState.InvincibleDash then
        --print("InvincibleDash")
        --_PlayAnim( 5 )

        _PlayAnim( 5 )
        self.animator:Play( "dash", -1 ) -- 动画瞬切


    elseif self.state == PlayerState.OnHit then
        print("OnHit")
        --self.animator:Play( "hit", -1 ) -- 动画瞬切
        --self:SetRoleFX( "fx_role_injured_jingji", true )

    end
end




function ParkourPlayerController:TryBackToCenter()
    if self.controller.transform.localPosition.x - self.centerPos <= -0.15 then
        self.isCenter = false
        self.rigidBody:AddForce(Vector3.right * self.backToCenterSpeed) -- todo 别用force
    elseif self.controller.transform.localPosition.x - self.centerPos >= 0.15 then
        self.isCenter = false
        self.rigidBody:AddForce(Vector3.left * self.backToCenterSpeed) -- todo 别用force
    elseif not self.isCenter then
        --self.controller.transform.localPosition = Vector3.zero
        local velocity = self.rigidBody.velocity
        self.rigidBody.velocity = Vector3(0, velocity.y, 0)
        local pos = self.controller.transform.localPosition
        self.controller.transform.localPosition = Vector3(self.centerPos, pos.y, pos.z)
        self.isCenter = true
    end
end

function ParkourPlayerController:_CheckOutOfRange()
    local pos = self.controller.transform.localPosition
    if (pos.x < -15 or pos.y < -5) and self.isOutOfRange == false then
        self.isOutOfRange = true
        Events.Broadcast(ParkourGameUtil.Events.RoleDead)
    end
end


function ParkourPlayerController:IsUnwounded()
    return (self.health == self.maxHp)
end

-- role 受到伤害
---@return boolean 
function ParkourPlayerController:OnHit()
    --printError("OnHit")
    if Mgr.debug.isInvincible then 
        return
    end

    if self.hitCD > 0 then 
        return false
    end 
  
    Events.Broadcast(ParkourGameUtil.Events.PlayerOnHit) -- buff 里实现此 event

    if (self.conditonState.shieldState ~= ParkourGameUtil.ShieldState.Closed) or self.conditonState.Invincible then
        -- 在此执行正式关闭
        if self.conditonState.shieldState == ParkourGameUtil.ShieldState.Closing then 
            self.conditonState.shieldState = ParkourGameUtil.ShieldState.Closed
        end 
        return false
    end

    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_broken_12001801" )

    self.hitCD = hitCDLen
    --self:ChangeState(PlayerState.OnHit) -- !! tpr
    self.health = self.health - 1
    Events.Broadcast(ParkourGameUtil.Events.PlayerTakeDamage, self.health)
    if self.health <= 0 then
        self:OnFail()
    end
    return true
end


-- 游戏失败表现流程:
function ParkourPlayerController:OnFail()
    CoStop(self.co_fail)
    self.co_fail = CoStart(function()

        self.forbidInput = true
    
        -- 等待 hit 特效播放一段时间:
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.2 ))
        Parkour_Loader.GetInstance():HideAllFX() -- 关闭所有fx
        ---
        Mgr.gameRunner:PauseGame()
        ---
        self.state = PlayerState.Dead
        self.animator:Play( "lose", -1 )
        self.rigidBody.velocity = Vector3.zero
        -- 特效
        cs_coroutine.yield_return(self:SetRoleFX( "fx_role_death", true, true ))
        ---
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1 ))
        Events.Broadcast(ParkourGameUtil.Events.RoleDead)
    end)
end



-- 游戏胜利表现流程:
function ParkourPlayerController:OnSuccess()
    CoStop(self.co_success)
    self.co_success = CoStart(function()

        self.forbidInput = true
        self:ChangeState(PlayerState.Idle)
        Parkour_Loader.GetInstance():HideAllFX() -- 关闭所有fx

        -- 等待 hit 特效播放一段时间:
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.2 ))

        Mgr.gameRunner:PauseGame()
        ---
        self.state = PlayerState.Win
        self.animator:Play( "win", -1 )
        self.rigidBody.velocity = Vector3.zero
        ---
        Events.Broadcast(ParkourGameUtil.Events.GameSuccessShowPanel)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1 ))
        Events.Broadcast(ParkourGameUtil.Events.GameSuccess)
    end)
end




---@param fxName_ string 
---@param isShow_ boolean 
---@param isInsideCoroutine_ boolean @ 本次函数调用是否在一个 协程内; (这样就不用自己再开协程了)
---@param isRootM_ boolean @ 石佛挂在 Root_M 节点下面
function ParkourPlayerController:SetRoleFX( fxName_, isShow_, isInsideCoroutine_, isRootM_ )

    local parentTF = isRootM_==true and self:GetRootM() or self.fxParentT
    if isNull(parentTF) then 
        parentTF = self.fxParentTF
    end 
    --printError("parent = " .. tostring(parentTF.name))
    Parkour_Loader.GetInstance():SetFX( fxName_, parentTF, isShow_, isInsideCoroutine_ )
end




---@param buff ParkourBuff.Buff
function ParkourPlayerController:AddBuff(buff)
    --printError("AddBuff")
    local ownBuff = self.buffs[buff.Type()]
    if ownBuff then
        ownBuff:AddSameBuff(buff)
    else
        self.buffs[buff.Type()] = buff
        buff:SetPlayer(self)
        buff:OnStart()
    end
end

function ParkourPlayerController:RemoveBuff(buff)
    self.buffs[buff.Type()] = nil
end


function ParkourPlayerController:_TickBuff(deltaTime)
    for k, v in pairs(self.buffs) do
        if v.alive then
            v:OnTick(deltaTime)
        else
            v:OnEnd()
            self.buffs[k] = nil
        end
    end
end


-- 检查 role 在 normal状态的 capsule collider 里是否会碰到东西, 如果会, 意味着不能从 slide 状态恢复回 run 状态
function ParkourPlayerController:_CheckRoleNormalCapsuleCollider( isdebug_ )

    local tf = self.controller.gameObject.transform
    local radius = ParkourGameUtil.roleSlideColliderHeight * 0.5
    local pos1 = tf.position + Vector3.up * radius
    local pos2 = tf.position + Vector3.up * (ParkourGameUtil.roleNormalColliderHeight - radius)

    pos1 = pos1 + Vector3.up * 0.02
    pos2 = pos2 + Vector3.up * 0.02
    local numFound = Physics.OverlapCapsuleNonAlloc(
        pos1, 
        pos2, 
        radius * 0.99, 
        self.colliders, 
        -1,     -- layerMask 暂时未设置
        QueryTriggerInteraction.Ignore
    ) 

    for i=0, numFound-1 do 
        local collider = self.colliders[i]
        if isNotNull(collider) and collider.transform ~= self.controller.transform and 
            ( collider.transform.position.y - self.controller.transform.position.y > 0.1 ) -- 不要被同层物体挡住
        then
            if isdebug_ == true then
                printError( "Touch XX-> " .. collider.name)
            end 
            return true
        end
    end
    return false
end



---@return UnityEngine.Transform | nil
function ParkourPlayerController:GetRootM() 
    if isNull(self.rootM) then 
        local tfComps = self.controller.transform:GetComponentsInChildren(typeof(Transform),true) -- 包含自己
        for i=0, tfComps.Length-1 do 
            local tf = tfComps[i]
            if isNotNull(tf) and string.lower(tf.name) == "root_m" then 
                self.rootM = tf
                break
            end 
        end
    end
    if isNull(self.rootM) then 
        printError("猫 prefab 骨骼下没找到 Root_M 节点")
    end 
    return self.rootM
end


return ParkourPlayerController